SELECT w.wheel_id, b.cheese, (SELECT c.weight_g FROM checks c WHERE c.wheel_id = w.wheel_id ORDER BY c.checked_on DESC, c.check_id DESC LIMIT 1) AS last_g, ROUND(100.0 * (w.start_g - (SELECT c.weight_g FROM checks c WHERE c.wheel_id = w.wheel_id ORDER BY c.checked_on DESC, c.check_id DESC LIMIT 1)) / w.start_g, 1) AS loss_pct
FROM wheels w JOIN batches b ON b.batch_id = w.batch_id
WHERE (SELECT c.weight_g FROM checks c WHERE c.wheel_id = w.wheel_id ORDER BY c.checked_on DESC, c.check_id DESC LIMIT 1) IS NOT NULL AND 100.0 * (w.start_g - (SELECT c.weight_g FROM checks c WHERE c.wheel_id = w.wheel_id ORDER BY c.checked_on DESC, c.check_id DESC LIMIT 1)) / w.start_g >= 8 ORDER BY loss_pct DESC, w.wheel_id;

